/* 
 * Implementing rot13 functionality based on disassembly analysis of rot13_char and rot13.
 * The assembly for rot13_char shows two branches:
 * 1. If input is between 0x61 ('a') and 0x7a ('z'): output = (input - 'a' + 13) % 26 + 'a'
 *    The asm uses a magic multiplier for modulo 26, which is common for compilers.
 * 2. If input is between 0x41 ('A') and 0x5a ('Z'): output = (input - 'A' + 13) % 26 + 'A'
 * 3. Otherwise: return original input byte.
 */

static int32_t rot13_char(int32_t c) {
    if (c >= 'a' && c <= 'z') {
        return (c - 'a' + 13) % 26 + 'a';
    } else if (c >= 'A' && c <= 'Z') {
        return (c - 'A' + 13) % 26 + 'A';
    }
    return c;
}

